toolArgs.file_text:
.step-indicator ol {
    counter-reset: step;
}

.step-circle {
    width: 36px;
    height: 36px;
    font-size: 0.875rem;
    font-weight: 600;
    line-height: 36px;
}

.step-item {
    position: relative;
}

.step-item:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 18px;
    left: calc(50% + 22px);
    width: calc(100% - 44px);
    height: 2px;
    background: #dee2e6;
    z-index: 0;
}

.step-item.completed:not(:last-child)::after {
    background: #198754;
}

.step-item.active:not(:last-child)::after {
    background: linear-gradient(to right, #0d6efd 50%, #dee2e6 50%);
}

button.step-circle {
    cursor: pointer;
    width: 36px;
    height: 36px;
    font-size: 0.875rem;
    font-weight: 600;
    line-height: 36px;
    padding: 0;
}

button.step-circle:hover {
    opacity: 0.85;
}

